from PIL import Image
import numpy as np, cv2
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(np.uint8)
for chname,g in [('gray',cv2.cvtColor(im,cv2.COLOR_RGB2GRAY)),('sat',(im.max(2)-im.min(2)).astype(np.uint8)),('redblue',(im[:,:,2].astype(int)-im[:,:,0]+128).clip(0,255).astype(np.uint8))]:
 edges=cv2.Canny(g,10,30)
 lines=cv2.HoughLinesP(edges,1,np.pi/720,threshold=15,minLineLength=20,maxLineGap=4)
 print('\\n',chname, 0 if lines is None else len(lines))
 if lines is not None:
  for l in lines[:80]:
   x1,y1,x2,y2=l[0]
   if y1>20 or y2>20: print((x1,y1,x2,y2),round(np.degrees(np.arctan2(y2-y1,x2-x1)),1))
PY"
